INSERT INTO email_templates (id, subject, html_content) VALUES
('order_received', 'We received your Lado Organics order {{order_number}}', '<div style="font-family:Arial,sans-serif;color:#2D241E;line-height:1.6"><h2>Namaste {{name}},</h2><p>We have received your order <strong>{{order_number}}</strong>.</p><p>Order total: <strong>₹{{amount}}</strong></p><p>Payment method: {{payment_method}}</p><p>Your order is currently awaiting confirmation. We will contact you with the next update.</p><p>With gratitude,<br/>Lado Organics</p></div>'),
('booking_request_received', 'Your Bhunga stay request has been received', '<div style="font-family:Arial,sans-serif;color:#2D241E;line-height:1.6"><h2>Namaste {{name}},</h2><p>We have received your Bhunga stay request for <strong>{{check_in}}</strong> to <strong>{{check_out}}</strong>.</p><p>Your request is pending availability confirmation by our farm team. Please wait for our confirmation before making travel arrangements.</p><p>With gratitude,<br/>Lado Organics</p></div>'),
('sponsorship_request_received', 'Your Gau Seva sponsorship request has been received', '<div style="font-family:Arial,sans-serif;color:#2D241E;line-height:1.6"><h2>Namaste {{name}},</h2><p>We have received your Gau Seva sponsorship request for <strong>{{calf_name}}</strong>.</p><p>Requested plan: {{plan}}. Recorded contribution amount: ₹{{amount}}.</p><p>This message acknowledges your request only. It is not a payment receipt or confirmation that funds have been received.</p><p>With gratitude,<br/>Lado Organics</p></div>')
